create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 in Oracle's DOW function, or check day of week number)
    -- TRUNC(date, 'IW') returns the Monday of the week. If the day is Monday to Friday, it's a working day.
    -- A simpler check is using TO_CHAR(l_day, 'DY') or checking the day of week number (1=Sunday, 7=Saturday).
    -- Oracle's standard day of week: Sunday=1, Monday=2, ..., Saturday=7.
    if to_char(l_day, 'D') not in ('1', '7') then -- Assuming 'D' returns 1 for Sunday and 7 for Saturday, or using ISO standard where Monday=1, Sunday=7.
                                                    -- For standard Oracle NLS settings, DOW is 1=Sunday to 7=Saturday.
      -- Let's use the standard Oracle DOW where 1=Sunday, 7=Saturday. Working days are 2 through 6.
      if to_char(l_day, 'D') in ('2', '3', '4', '5', '6') then
        l_count := l_count + 1;
      end if;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/
